def main():
    out = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'app', 'src', 'main', 'assets', 'i18n', 'mobile.tsv')
    seen = set()
    with open(out, 'w', encoding='utf-8', newline='\n') as f:
        f.write('# 모바일 전용 번역 — android/tools/mobile_i18n.py 에서 만듦 (거기서 고칠 것)\n')
        for e in E:
            assert len(e) == 3, e
            if e[0] in seen:
                raise SystemExit('dup: ' + e[0])
            seen.add(e[0])
            f.write('\t'.join(x.replace('\t', '\\t').replace('\n', '\\n') for x in e) + '\n')
    print(len(E), 'entries →', out)


if __name__ == '__main__':
    main()
